const $=s=>document.querySelector(s);let saved={};try{saved=JSON.parse(localStorage.getItem('sql-praktikum-v1')||'{}')}catch{};let current=Number.isInteger(saved.current)&&saved.current>=1&&saved.current<=tasks.length?saved.current:1;let solved=new Set(Array.isArray(saved.solved)?saved.solved:[]),drafts=saved.drafts||{},worker,busy=false,ready=false,timer,requestId=0;
const esc=v=>String(v===null?'NULL':v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function persist(){try{localStorage.setItem('sql-praktikum-v1',JSON.stringify({current,solved:[...solved],drafts}))}catch{}}
function list(){const filter=$('#level').value;let group='';$('#task-list').innerHTML=tasks.filter(t=>filter==='Все уровни'||t.level===filter).map(t=>{const g=t.level!==group?`<div class="group-label">${t.level==='Лёгкая'?'01 · ОСНОВЫ':t.level==='Средняя'?'02 · АНАЛИЗ ДАННЫХ':t.level==='Сложная'?'03 · НА ШАГ ДАЛЬШЕ':'04 · ЭКСПЕРТНЫЙ УРОВЕНЬ'}</div>`:'';group=t.level;return g+`<button class="task-item ${current===t.id?'selected':''} ${solved.has(t.id)?'solved':''}" data-task="${t.id}" ${current===t.id?'aria-current="step"':''}><span class="task-index">${solved.has(t.id)?'✓':String(t.id).padStart(2,'0')}</span><span>${t.title}</span></button>`}).join('');$('#progress-count').textContent=`${solved.size} из ${tasks.length}`;$('#progress-bar').style.width=solved.size/tasks.length*100+'%';}
function lines(){$('#line-numbers').innerHTML=$('#editor').value.split('\n').map((_,i)=>i+1).join('<br>')}
function selectTask(id){if(busy)return;current=id;const t=tasks[id-1];$('#task-number').textContent='ЗАДАЧА '+String(id).padStart(2,'0');$('#difficulty').textContent=t.level;$('#task-title').textContent=t.title;$('#task-description').textContent=t.text;$('#hint-text').textContent=t.hint;$('#solution-text').textContent=t.answer;$('#hint').open=false;$('#solution').open=false;$('#editor').value=drafts[id]??t.starter;$('#feedback').textContent='';$('#feedback').className='';$('#result').innerHTML='<div class="empty-state"><span>⌘</span><h3>Здесь появятся ваши данные</h3><p>Напишите запрос и нажмите «Запустить»</p></div>';$('#result-meta').textContent='—';$('#expected-columns').textContent=t.columns?.join(', ')||t.answer.match(/^SELECT (.*?) FROM/i)?.[1]||'Результат SELECT';$('#order-note').textContent=t.ordered?'Порядок строк важен.':'Порядок строк не важен.';$('#prev').disabled=id===1;$('#next').disabled=id===tasks.length;lines();list();persist();}
function feedback(text,cls=''){$('#feedback').textContent=text;$('#feedback').className=cls}
function controls(){$('#run').disabled=!ready||busy;$('#check').disabled=!ready||busy;$('#check').textContent=busy?'Выполняется…':'Проверить решение';}
function startWorker(){ready=false;controls();worker=new Worker('engine.js');worker.onmessage=({data})=>{if(data.ready){ready=true;controls();return}if(data.id!==requestId)return;clearTimeout(timer);busy=false;controls();if(data.error){feedback('Ошибка SQL: '+data.error,'error');$('#result').innerHTML='';$('#result-meta').textContent='Ошибка';return}const r=data.result;$('#result').innerHTML='<table><thead><tr>'+r.columns.map(c=>'<th>'+esc(c)+'</th>').join('')+'</tr></thead><tbody>'+r.values.map(row=>'<tr>'+row.map(c=>'<td>'+esc(c)+'</td>').join('')+'</tr>').join('')+'</tbody></table>';$('#result-meta').textContent=r.values.length+' строк';if(data.correct===true){solved.add(current);persist();list();feedback('✓ Всё верно! Задача решена. Можно переходить к следующей.','success')}else if(data.correct===false)feedback('Пока не совпадает. Проверьте столбцы, значения и условия задачи. Подсказка поможет.','error');else feedback(r.values.length?'Запрос выполнен. Нажмите «Проверить решение», чтобы зачесть задачу.':'Запрос выполнен. Строки не найдены.');};worker.onerror=()=>{clearTimeout(timer);busy=false;ready=false;controls();feedback('Не удалось загрузить SQL-движок. Обновите страницу и попробуйте снова.','error')}}
function run(check=false,sql=$('#editor').value){if(busy||!ready)return;if(!sql.trim()){feedback('Напишите SQL-запрос.','error');return}busy=true;controls();feedback('Выполняем запрос…');const id=++requestId;worker.postMessage({sql,check,task:current,id});timer=setTimeout(()=>{worker.terminate();busy=false;startWorker();feedback('Запрос остановлен: превышен лимит 4 секунды. Упростите запрос.','error')},4000)}
$('#task-list').onclick=e=>{const b=e.target.closest('[data-task]');if(b)selectTask(+b.dataset.task)};$('#level').onchange=list;$('#editor').oninput=()=>{drafts[current]=$('#editor').value;persist();lines()};$('#editor').onscroll=()=>{$('#line-numbers').scrollTop=$('#editor').scrollTop};$('#editor').onkeydown=e=>{if(e.key==='Enter'&&(e.ctrlKey||e.metaKey)){e.preventDefault();run()}if(e.key==='Tab'){e.preventDefault();const el=e.target;el.setRangeText('  ',el.selectionStart,el.selectionEnd,'end');el.dispatchEvent(new Event('input'))}};
$('#run').onclick=()=>run();$('#check').onclick=()=>run(true);$('#reset').onclick=()=>{if(busy)return;delete drafts[current];selectTask(current)};$('#prev').onclick=()=>selectTask(Math.max(1,current-1));$('#next').onclick=()=>selectTask(Math.min(tasks.length,current+1));
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-view]').forEach(n=>n.classList.toggle('active',n===b));$('#practice-view').hidden=b.dataset.view!=='practice';$('#reference-view').hidden=b.dataset.view!=='reference'});
document.querySelectorAll('[data-panel]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-panel]').forEach(n=>n.classList.toggle('active',n===b));$('#condition').hidden=b.dataset.panel!=='condition';$('#schema').hidden=b.dataset.panel!=='schema'});
const schema={customers:['id INTEGER · ключ','name TEXT · имя','city TEXT · город'],products:['id INTEGER · ключ','name TEXT · название','category TEXT · категория','price INTEGER · цена, ₽'],orders:['id INTEGER · ключ','customer_id INTEGER · покупатель','product_id INTEGER · товар','quantity INTEGER · количество','order_date TEXT · YYYY-MM-DD','status TEXT · статус']};$('#schema-tables').innerHTML=Object.entries(schema).map(([name,cols])=>`<div class="schema-card"><button data-table="${name}" title="Посмотреть данные">▤ ${name} · данные</button><p>${cols.join('<br>')}</p></div>`).join('');$('#schema-tables').onclick=e=>{const b=e.target.closest('[data-table]');if(b)run(false,'SELECT * FROM '+b.dataset.table)};
const refs=[['SELECT и FROM','Выбирайте столбцы через запятую или используйте * для всех столбцов.','SELECT name, city\nFROM customers;'],['WHERE','Оставляет строки, удовлетворяющие условию. Используйте AND, OR, IN и BETWEEN.',"SELECT * FROM products\nWHERE price BETWEEN 1000 AND 5000;"],['ORDER BY и LIMIT','Сортировка ASC — по возрастанию, DESC — по убыванию. LIMIT ограничивает число строк.','SELECT name, price FROM products\nORDER BY price DESC LIMIT 3;'],['GROUP BY','Объединяет строки в группы. COUNT, SUM, AVG, MIN и MAX вычисляют значения для группы.','SELECT city, COUNT(*) AS total\nFROM customers GROUP BY city;'],['JOIN','INNER JOIN возвращает совпадения. LEFT JOIN сохраняет все строки левой таблицы.','SELECT o.id, c.name\nFROM orders o JOIN customers c\nON c.id = o.customer_id;'],['HAVING','Фильтрует группы после GROUP BY. WHERE фильтрует строки до группировки.','SELECT city, COUNT(*) AS total\nFROM customers GROUP BY city\nHAVING COUNT(*) > 1;'],['Подзапросы','Результат одного SELECT можно использовать внутри другого запроса.','SELECT name FROM products\nWHERE price >\n(SELECT AVG(price) FROM products);'],['Оконные функции','Вычисляют значение по набору строк, сохраняя отдельные строки результата.','SELECT name, DENSE_RANK() OVER\n(ORDER BY price DESC) AS place\nFROM products;']];$('#reference-grid').innerHTML=refs.map(([title,description,sql])=>`<article class="reference-card"><h2>${title}</h2><p>${description}</p><pre>${esc(sql)}</pre></article>`).join('');
selectTask(current);startWorker();
if(document.modelContext?.registerTool){const lifecycle=new AbortController();try{Promise.resolve(document.modelContext.registerTool({name:'select_sql_exercise',description:'Open a SQL exercise by its number.',inputSchema:{type:'object',properties:{id:{type:'integer',minimum:1,maximum:tasks.length}},required:['id'],additionalProperties:false},annotations:{readOnlyHint:false},execute:({id})=>{if(!Number.isInteger(id)||id<1||id>tasks.length)throw new Error('Invalid exercise');if(busy)throw new Error('Query running');selectTask(id);return {id,title:tasks[id-1].title,description:tasks[id-1].text}}},{signal:lifecycle.signal})).catch(()=>{});addEventListener('pagehide',()=>lifecycle.abort(),{once:true})}catch{}}
